import type{EditBlueprint,PromptPack}from"../../core/contracts"
import{compileEditBlueprint}from"../../core/edit-timeline"
import{compilePromptPack}from"../../core/prompt-pack"
import{approvedEditScript}from"./edit-blueprint"
export function approvedPromptBlueprint(runId="prompt-fixture"):EditBlueprint{const b=compileEditBlueprint(approvedEditScript(runId)),s=b.shots.find(x=>x.representationType==="DRAMATIZATION");if(s){const originalRequest=b.assetRequests.find(x=>x.shotId===s.shotId)!;const screen={...structuredClone(s),shotId:`${s.shotId}-screen`,assetRequestId:`${s.assetRequestId}-screen`,shotType:"SCREEN_RECREATION"as const,representationType:"FICTIONAL_INTERFACE"as const,labelRequired:true};b.shots.push(screen);b.assetRequests.push({...structuredClone(originalRequest),assetRequestId:screen.assetRequestId,shotId:screen.shotId,representationType:"FICTIONAL_INTERFACE",sourceMode:"RECONSTRUCTED",downstreamAgent:"image-agent"});b.sequences.find(x=>x.sequenceId===s.sequenceId)?.shotIds.push(screen.shotId);s.shotType="MEDIUM_HUMAN_ACTION";s.assetType="GENERATED_VIDEO";originalRequest.assetType="GENERATED_VIDEO";originalRequest.downstreamAgent="video-agent"}return b}
export function approvedPromptPack():PromptPack{return compilePromptPack(approvedPromptBlueprint())}
export function negativePromptPack():PromptPack{const p=structuredClone(approvedPromptPack());p.prompts[0].postProductionRequirements=[];p.prompts[0].negativeConstraints=[];p.prompts[0].rejectionCriteria=[];p.prompts[0].evidenceTreatment.boundary=null as never;p.referenceManifests[0].references[0].status="MISSING";if(p.videoSpecs[0]){delete p.videoSpecs[0].startFrameReferenceId;delete p.videoSpecs[0].startFrameHash}p.providerCapabilityRequirements=p.providerCapabilityRequirements.filter(x=>x.importance!=="CRITICAL");p.dependencyGraph.edges.push({from:`qc-${p.prompts[0].promptId}`,to:p.prompts[0].promptId,relation:"REQUIRES"});p.budgetUsage.withinLimits=false;p.status="BLOCKED";return p}
